/* MRT-6 corridor 3D: streamed, map-aligned OpenStreetMap building footprints.
 * Uses compact offline z15 OSM tiles generated by build-dhaka-city-tiles.py.
 * Until workflow data is published, uses the 16 existing OSM station snapshots.
 * Facade colors and OSM-missing heights are explicitly approximations.
 */
(() => {
"use strict";
const C = window.Cesium;
const btn = document.getElementById("cityToggle");
const status = document.getElementById("cityStatus");
if (!C || !btn || !status) return;
const MOBILE = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
const MAX_TILES = MOBILE ? 4 : 7;
const MAX_PER_TILE = MOBILE ? 480 : 900;
const MAX_HEIGHT = 6800;
const colors = ["#d3c5b4","#cda58f","#b9cdd4","#a6b3b5","#c7b89c","#e0b8a3","#e0d8c8"];
let viewer, track, enabled = false, ready = false, manifest = null, epoch = 0;
const active = new Map(), pending = new Map(), failed = new Set();
let lastUpdate = 0;
const name = v => v ? "🚇 Corridor ON" : "🏙 Corridor 3D";
const message = s => { status.hidden = false; status.textContent = s; };
const num = n => Number.isFinite(Number(n)) ? Number(n) : 0;
function getColor(i, seed){
 const css = colors[(i % 5 + seed % colors.length) % colors.length];
 return C.Color.fromCssColorString(css);
}
function makeGeometry(records) {
 const instances = [];
 for (let i=0;i<records.length && instances.length<MAX_PER_TILE;i++){
  const rec=records[i], ring=Array.isArray(rec)?rec[0]:rec.p;
  if (!Array.isArray(ring)||ring.length<3||ring.length>110) continue;
  const coords=[];
  for(const p of ring){
   if(Array.isArray(p)&&Number.isFinite(+p[0])&&Number.isFinite(+p[1])) coords.push(+p[0],+p[1]);
  }
  if(coords.length<6)continue;
  if(coords[0]===coords[coords.length-2]&&coords[1]===coords[coords.length-1]) coords.splice(-2);
  if(coords.length<6)continue;
  const rawH=Array.isArray(rec)?num(rec[1]):num(rec.h);
  // Unknown OSM height is visualized, not asserted, as a reproducible estimate.
  const seed = Math.abs(Math.round(coords[0]*100000+coords[1]*150000));
  const h=rawH>2 && rawH<320 ? rawH : 8+(seed%7)*3.2;
  const category=Array.isArray(rec)?num(rec[2]):0;
  try {
   const geometry=new C.PolygonGeometry({
    polygonHierarchy:new C.PolygonHierarchy(C.Cartesian3.fromDegreesArray(coords)),
    height:h,extrudedHeight:0,closeTop:true,closeBottom:true,
    vertexFormat:C.PerInstanceColorAppearance.VERTEX_FORMAT
   });
   instances.push(new C.GeometryInstance({
    geometry,attributes:{color:C.ColorGeometryInstanceAttribute.fromColor(getColor(category,seed))}
   }));
  }catch(e){ /* Ignore malformed OSM polygons without inventing geometry. */ }
 }
 if(!instances.length)return null;
 return new C.Primitive({
  geometryInstances:instances,
  appearance:new C.PerInstanceColorAppearance({closed:true,translucent:false}),
  asynchronous:true,allowPicking:false,releaseGeometryInstances:true
 });
}
function removeKey(k){
 const obj=active.get(k);
 if(obj){try{viewer.scene.primitives.remove(obj)}catch(e){} active.delete(k);}
}
function removeAll(){for(const k of [...active.keys()])removeKey(k);}
function xy(lon,lat,z){
 const n=2**z,latRad=C.Math.toRadians(Math.max(-85,Math.min(85,lat)));
 return [Math.floor((lon+180)/360*n),
         Math.floor((1-Math.asinh(Math.tan(latRad))/Math.PI)/2*n)];
}
function center(){
 const canvas=viewer.canvas;
 const point=new C.Cartesian2(canvas.clientWidth/2,canvas.clientHeight/2);
 const p=viewer.camera.pickEllipsoid(point,viewer.scene.globe.ellipsoid);
 if(!p)return null;
 const c=C.Cartographic.fromCartesian(p);
 return {lon:C.Math.toDegrees(c.longitude),lat:C.Math.toDegrees(c.latitude)};
}
async function fetchJSON(url){
 const res=await fetch(url,{cache:"force-cache"});
 if(!res.ok)throw Error("HTTP "+res.status);
 return res.json();
}
async function show(key,url,generation){
 if(active.has(key)||pending.has(key)||failed.has(key))return;
 const task=(async()=>{
  try {
   const data=await fetchJSON(url);
   if(!enabled||generation!==epoch)return;
   const rows=Array.isArray(data)?data:data.buildings;
   if(!Array.isArray(rows)||rows.length<1)throw Error("Empty mapped OSM tile");
   const primitive=makeGeometry(rows);
   if(!primitive)return;
   viewer.scene.primitives.add(primitive);
   active.set(key,primitive);
   message("বাস্তব OSM building footprint 3D: "+active.size+"টি এলাকা লোড। রং ও অজানা উচ্চতা অনুমানভিত্তিক।");
  }catch(e){failed.add(key);if(active.size===0)message("এই এলাকার OSM 3D tile অনুপস্থিত। বেস ম্যাপ দেখা যাবে।");}
  finally{pending.delete(key);}
 })();
 pending.set(key,task);
 await task;
}
function closestStation(lon,lat){
 let best=-1,d=Infinity;
 track.stations.forEach((s,i)=>{
  const dist=Math.hypot((lon-s.lon)*101000,(lat-s.lat)*111200);
  if(dist<d){d=dist;best=i;}
 });
 return d<1600?best:-1;
}
async function update(){
 if(!enabled||!viewer)return;
 const now=Date.now();if(now-lastUpdate<300)return;lastUpdate=now;
 const h=viewer.camera.positionCartographic.height;
 if(h>MAX_HEIGHT){removeAll();message("3D ভবন দেখতে ক্যামেরা নিচে নামান বা স্টেশন নির্বাচন করুন।");return;}
 const p=center();if(!p)return;
 const generation=++epoch;
 let desired=[];
 if(ready&&manifest){
  const [west,south,east,north]=manifest.bounds;
  if(p.lon>=west&&p.lon<=east&&p.lat>=south&&p.lat<=north){
   const z=manifest.zoom,[x,y]=xy(p.lon,p.lat,z);
   for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){
    desired.push({key:"t/"+z+"/"+(x+dx)+"/"+(y+dy),path:"data/3d-city/t/"+z+"/"+(x+dx)+"/"+(y+dy)+".json",dist:dx*dx+dy*dy});
   }
   desired.sort((a,b)=>a.dist-b.dist);desired=desired.slice(0,MAX_TILES);
  }
 }
 if(!desired.length){
  const k=closestStation(p.lon,p.lat);
  if(k>=0) desired=[{key:"station/"+k,path:"data/buildings/"+k+".json"}];
 }
 const keys=new Set(desired.map(x=>x.key));
 for(const k of [...active.keys()])if(!keys.has(k))removeKey(k);
 if(!desired.length){message("এই অঞ্চলের ভবন এখনো ম্যাপ করা হয়নি। OSM বেসম্যাপ সক্রিয়।");return;}
 message("ঢাকার মানচিত্রভিত্তিক ভবন লোড হচ্ছে…");
 // Avoid concurrent memory spikes on iPhone and obsolete camera loads.
 for(const item of desired){
  if(!enabled||epoch!==generation)return;
  await show(item.key,item.path,generation);
 }
}
async function initialize(){
 try{
  manifest=await fetchJSON("data/3d-city/manifest.json");
  ready=manifest.ready===true && Array.isArray(manifest.bounds) && Number.isInteger(manifest.zoom);
 }catch(e){ready=false;}
 if(ready)message("মেট্রোরেল corridor OSM 3D tiles প্রস্তুত। স্টেশনে zoom করলে ভবন দেখা যাবে।");
 else message("২৫০ মিটার corridor tile build এখনো শেষ হয়নি; স্টেশন এলাকার OSM ভবন দেখা যাবে।");
 if(enabled)update();
}
btn.onclick=()=>{
 enabled=!enabled;epoch++;
 btn.classList.toggle("active",enabled);
 btn.textContent=name(enabled);
 btn.setAttribute("aria-pressed",String(enabled));
 if(enabled){status.hidden=false;update();}
 else {removeAll();status.hidden=true;}
};
function setup(){
 if(viewer)return;
 const full=window.MRTFullLine3D;
 if(!full||!full.viewer)return;
 viewer=full.viewer;track={stations:full.stations};
 viewer.camera.moveEnd.addEventListener(update);
 initialize();
}
window.addEventListener("mrt3dready",setup,{once:true});
setup();
})();
